(()=>{'use strict';document.querySelector('.intro-overlay').hidden=true;document.querySelector('.intro-skip').hidden=true;
const section=document.querySelector('.longshot'),nav=document.querySelector('.nav');function onScroll(){const r=section.getBoundingClientRect(),hide=r.top<-innerHeight+80&&r.bottom>0;nav.classList.toggle('is-hidden',hide);nav.inert=hide;nav.setAttribute('aria-hidden',String(hide))}addEventListener('scroll',onScroll,{passive:true});onScroll();
const tabs=[...document.querySelectorAll('[data-case]')];function select(t){tabs.forEach(b=>{let on=b===t;b.setAttribute('aria-selected',on);b.tabIndex=on?0:-1;document.querySelector('#case-'+b.dataset.case).hidden=!on})}tabs.forEach((b,i)=>{b.addEventListener('click',()=>select(b));b.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();let n=tabs[(i+(e.key==='ArrowRight'?1:tabs.length-1))%tabs.length];select(n);n.focus()})});
document.querySelectorAll('[data-finish]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-finish]').forEach(x=>x.setAttribute('aria-pressed',x===b));let img=document.querySelector('#finish-image');img.src='assets/b2/ring-'+b.dataset.finish+'.png';img.alt=b.dataset.label+' Vocci ring';document.querySelector('#finish-label').textContent=b.dataset.label}));
const faqs=[...document.querySelectorAll('[data-faq]')];function faq(t){faqs.forEach(b=>{let on=b===t;b.setAttribute('aria-selected',on);b.tabIndex=on?0:-1;document.querySelector('#faq-'+b.dataset.faq).hidden=!on})}faqs.forEach((b,i)=>{b.addEventListener('click',()=>faq(b));b.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();let n=faqs[(i+(e.key==='ArrowRight'?1:faqs.length-1))%faqs.length];faq(n);n.focus()})});
})();
